import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;
import static org.junit.jupiter.api.Assertions.assertAll;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePackedFtreeQuote.Site;
import org.junit.jupiter.api.Test;

class LmdbNativePackedFtreeChunkOpenQuoteTest {

	@Test
	void theFirstRowDoesNotPayTheSetupOfEveryFutureRootChunk() {
		LmdbNativeCostQuote quote = quote(1_000_000);
		assertThat(quote.forSlice(1D).expected(Feature.OPEN)).isEqualTo(1D);
	}

	@Test
	void aSliceAtTheFirstChunkBoundaryHasNotStartedTheSecondChunk() {
		LmdbNativeCostQuote quote = quote(1_000_000);
		double firstChunkRows = LmdbNativePackedFtree.ROOT_BATCH_SIZE * 9D;
		assertThat(quote.forSlice(firstChunkRows).expected(Feature.OPEN)).isEqualTo(1D);
		assertThat(quote.forSlice(firstChunkRows + 1D).expected(Feature.OPEN)).isEqualTo(2D);
	}

	@Test
	void aZeroRowSliceDoesNotStartChunkConstruction() {
		assertThat(quote(1_000_000).forSlice(0D).expected(Feature.OPEN)).isZero();
	}

	@Test
	void consumingAllRowsStillPaysOneSetupPerRootChunk() {
		LmdbNativeCostQuote quote = quote(1_000_000);
		double chunks = Math.ceil(1_000_000D / LmdbNativePackedFtree.ROOT_BATCH_SIZE);
		assertThat(quote.total().expected(Feature.OPEN)).isEqualTo(chunks);
		assertThat(quote.forSlice(9_000_000D).expected(Feature.OPEN)).isEqualTo(chunks);
	}

	@Test
	void aSmallDomainOnlyHasOneChunkToSetUp() {
		LmdbNativeCostQuote quote = quote(16);
		assertThat(quote.forSlice(1D).expected(Feature.OPEN)).isEqualTo(1D);
		assertThat(quote.total().expected(Feature.OPEN)).isEqualTo(1D);
	}

	@Test
	void aParallelWaveStartsItsPhysicalChunksWithoutChangingTheFullSetupCount() {
		LmdbNativeCostQuote serial = quote(1_000_000);
		LmdbNativeCostQuote parallel = new LmdbNativeCostQuote(serial.startup(), serial.streaming().scale(0.5D),
				serial.outputRows(), false, false,
				serial.chunked().scaled(0.5D, 2 * LmdbNativePackedFtree.ROOT_BATCH_SIZE));
		assertThat(parallel.forSlice(1D).expected(Feature.OPEN)).isEqualTo(2D);
		assertThat(parallel.total().expected(Feature.OPEN)).isEqualTo(serial.total().expected(Feature.OPEN));
	}

	@Test
	void checkingAnEmptyRootDomainStillHasOneInitialSetupAttempt() {
		// Runtime.nextChunk creates its reusable Chunk before roots.fill can report exhaustion. This is
		// different from a zero-row slice on a nonempty producer, which need not request its first chunk.
		assertThat(quote(0).total().expected(Feature.OPEN)).isEqualTo(1D);
	}

	@Test
	void anExactEmptyAdjacencyDomainDoesNotInventAChildLane() {
		LmdbNativeCostQuote quote = quote(0);
		assertAll(
				() -> assertThat(quote.chunked().rootCount()).isZero(),
				() -> assertThat(quote.chunked().acceptedRootCount()).isZero(),
				() -> assertThat(quote.total().expected(Feature.INDEX_SEEK)).isZero(),
				() -> assertThat(quote.total().expected(Feature.SCANNED_ROW)).isZero(),
				() -> assertThat(quote.total().expected(Feature.BATCH_ROW)).isZero(),
				() -> assertThat(quote.total().expected(Feature.OPEN)).isEqualTo(1D));
	}

	private static LmdbNativeCostQuote quote(int roots) {
		StatsSource source = new StatsSource(10_000_000L).predicate(1L, 3D, roots)
				.predicate(2L, 3D, roots)
				.adjacencyServed(true);
		RowState row = row(source);
		try {
			MultiJoinPlan join = new MultiJoinPlan(
					new PatternPlan[] { edge(0, 1L, 1, roots * 3D), edge(0, 2L, 2, roots * 3D) },
					new MaskedFilter[0]);
			LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(join, row, new int[] { 0, 1, 2 });
			assertThat(plan).isNotNull();
			assertThat(plan.root.slot).isZero();
			LmdbNativeCostQuote quote = LmdbNativePackedFtreeQuote.quote(plan, row, Site.ROWS, 0L, roots * 9D);
			assertThat(quote).isNotNull();
			return quote;
		} finally {
			row.memoryScope.close();
		}
	}
}
